def number_of_substrings(s: str) -> int:
    # For each right edge, find the last position where all three letters
    # have appeared; every start at or before it yields a valid substring.
    last = {'a': -1, 'b': -1, 'c': -1}
    total = 0
    for i, ch in enumerate(s):
        last[ch] = i
        if min(last.values()) >= 0:
            total += min(last.values()) + 1
    return total

