#include <bits/stdc++.h>
using namespace std;

int numberOfSubstrings(string s) {
    int last[3] = {-1, -1, -1};
    long long total = 0;
    for (int i = 0; i < (int)s.size(); ++i) {
        last[s[i] - 'a'] = i;
        int earliest = min({last[0], last[1], last[2]});
        if (earliest >= 0) total += earliest + 1;
    }
    return (int)total;
}

